    }
    )
    }
    

    
    /**
     * The engine decided this link is dead (nothing heard for 14 s): close it so it can be dialed again.
     */override fun `close`(`peer`: kotlin.String)
        = 
    callWithPointer {
    uniffiRustCall() { _status ->
