    }
    
    

    
    /**
     * Publish an encoded sealed blob. True if at least one service took it.
     */override fun `signalPut`(`mailbox`: kotlin.String, `blob`: kotlin.String, `kind`: SignalKind, `ttlSec`: kotlin.UInt): kotlin.Boolean {
