/**
 * @suppress
 */
public object FfiConverterTypeTransportCallbacks: FfiConverter<TransportCallbacks, Pointer> {
    internal val handleMap = UniffiHandleMap<TransportCallbacks>()

    override fun lower(value: TransportCallbacks): Pointer {
        return Pointer(handleMap.insert(value))
    }

    override fun lift(value: Pointer): TransportCallbacks {
        return TransportCallbacksImpl(value)
    }

    override fun read(buf: ByteBuffer): TransportCallbacks {
        // The Rust code always writes pointers as 8 bytes, and will
        // fail to compile if they don't fit.
        return lift(Pointer(buf.getLong()))
    }

    override fun allocationSize(value: TransportCallbacks) = 8UL

    override fun write(value: TransportCallbacks, buf: ByteBuffer) {
        // The Rust code always expects pointers written as 8 bytes,
        // and will fail to compile if they don't fit.
        buf.putLong(Pointer.nativeValue(lower(value)))
    }
}



