/**
 * How a link is protected. `Encrypted` is a WebRTC data channel (already encrypted by DTLS): the engine uses the
 * handshake the existing apps speak and plain frames. `Open` is a link that is not encrypted (Bluetooth): the engine
 * encrypts every frame itself.
 */

enum class LinkKind {
    
    ENCRYPTED,
    OPEN;
    companion object
}


/**
 * @suppress
 */
public object FfiConverterTypeLinkKind: FfiConverterRustBuffer<LinkKind> {
    override fun read(buf: ByteBuffer) = try {
        LinkKind.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: LinkKind) = 4UL

    override fun write(value: LinkKind, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}





sealed class LinkState {
    
    object Offline : LinkState()
    
    
    object Connecting : LinkState()
    
    
    data class Connected(
        val `path`: PathKind) : LinkState() {
        companion object
    }
    
    data class Reconnecting(
        val `attempt`: kotlin.UInt) : LinkState() {
        companion object
    }
    
    data class Failed(
        val `authentication`: kotlin.Boolean) : LinkState() {
        companion object
    }
    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeLinkState : FfiConverterRustBuffer<LinkState>{
    override fun read(buf: ByteBuffer): LinkState {
        return when(buf.getInt()) {
            1 -> LinkState.Offline
            2 -> LinkState.Connecting
            3 -> LinkState.Connected(
                FfiConverterTypePathKind.read(buf),
                )
            4 -> LinkState.Reconnecting(
                FfiConverterUInt.read(buf),
                )
            5 -> LinkState.Failed(
                FfiConverterBoolean.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: LinkState) = when(value) {
        is LinkState.Offline -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is LinkState.Connecting -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is LinkState.Connected -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypePathKind.allocationSize(value.`path`)
            )
        }
        is LinkState.Reconnecting -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterUInt.allocationSize(value.`attempt`)
            )
        }
        is LinkState.Failed -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterBoolean.allocationSize(value.`authentication`)
            )
        }
    }

    override fun write(value: LinkState, buf: ByteBuffer) {
        when(value) {
            is LinkState.Offline -> {
                buf.putInt(1)
                Unit
            }
            is LinkState.Connecting -> {
                buf.putInt(2)
                Unit
            }
            is LinkState.Connected -> {
                buf.putInt(3)
                FfiConverterTypePathKind.write(value.`path`, buf)
                Unit
            }
            is LinkState.Reconnecting -> {
                buf.putInt(4)
                FfiConverterUInt.write(value.`attempt`, buf)
                Unit
            }
            is LinkState.Failed -> {
                buf.putInt(5)
                FfiConverterBoolean.write(value.`authentication`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}






